 {"author": "Matthieu Pageau", "title": "The Language of Creation: Cosmic Symbolism in Genesis", "year": 2018, "level": "deeper", "why": "A modern Orthodox reading of Genesis as heaven and earth, meaning and matter."},
 {"author": "Augustine", "title": "Confessions, Books XI–XIII", "year": 400, "level": "deeper", "why": "The oldest great Christian reading of Genesis 1, written as a prayer."},
